questionvariables.text:
/*
Shared Curriculum-Independent
Question Bank

Linear Relations
QLIN-08

Adaptation source:
NUMBAS-17290

Licence:
CC BY 4.0

The source provides the licensed
straight-line graph question family
used as the adaptation basis.

This STACK implementation uses new
wording, generated values, two
relations with a guaranteed integer
intersection, and diagnostic feedback.
*/


/*
Choose the intersection first.

xI is non-zero so the intersection is
not simply the shared y-intercept.
*/

xI:rand_with_prohib(
    -2,
    2,
    [0]
);


yI:rand_with_prohib(
    -2,
    2,
    [xI]
);


/*
Generate two distinct non-horizontal
gradients.
*/

m1:rand_with_prohib(
    -2,
    2,
    [0]
);


m2:rand_with_prohib(
    -2,
    2,
    [0,m1]
);


/*
Construct both intercepts so both
relations pass through (xI,yI).

Because m1 is different from m2,
the two lines have exactly one
intersection.
*/

c1:yI-m1*xI;

c2:yI-m2*xI;


/*
Correct ordered pair.
*/

intersection:[xI,yI];


/*
Common misconception answers.

Learner may report a y-intercept
instead of the intersection.
*/

interceptA:[0,c1];

interceptB:[0,c2];


/*
Coordinate-order confusion.
*/

reversed:[yI,xI];
